update pages set contenu = '{"sections":[]}'::jsonb where path = '/expertises/types-de-maintenance/maintenance-curative/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance curative","mecanisme":"La réparation définitive, celle qui traite la cause et pas seulement l''effet. Cette page donne la définition, le déroulé d''une intervention curative et le calcul réparer ou remplacer. Puis elle dit qui exécute, et comment.","cta":"Demander une intervention","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option."},{"type":"chiffres","chiffres":[{"valeur":"Après un dépannage provisoire.","libelle":"La palliative a fait repartir la ligne, la curative vient solder la dette technique quelques jours plus tard."},{"valeur":"Sur une panne récurrente.","libelle":"Troisième arrêt en six mois sur le même équipement : il est temps de chercher la vraie cause."},{"valeur":"Sur un matériel en fin de vie.","libelle":"La réparation devient l''occasion de trancher entre remise en état et remplacement."},{"valeur":"Après une analyse de fiabilité.","libelle":"Les données de la GMAO désignent un organe fautif, on le traite pour de bon."},{"valeur":"+ 120","libelle":"clients industriels, dont plus de 80 réguliers","detail":"La plupart sont arrivés par une panne, et sont restés pour la méthode"},{"valeur":"10 %","libelle":"des candidats retenus, chaque technicien est évalué en entretien technique et comportemental"},{"valeur":"+ 100","libelle":"collaborateurs, depuis quatre agences, avec la même politique de sécurité partout"}],"reponse":[{"texte":"Toute maintenance curative est corrective. L''inverse est faux, puisque le dépannage palliatif appartient lui aussi à la corrective."}]},{"type":"probleme","punchline":"La rustine posée en urgence il y a six mois tient toujours, et tout le monde a oublié pourquoi.","puces":[{"accroche":"Les dépannages provisoires s''empilent.","texte":"Personne ne programme jamais la réparation de fond, et les mêmes pannes reviennent à un rythme de plus en plus court."},{"accroche":"Le diagnostic prend le temps qu''on ne lui donne pas.","texte":"Sous pression, on remplace ce qui a cassé. Chercher l''alignement fautif demande une demi-journée que le planning refuse."},{"accroche":"La connaissance repart avec l''intervenant.","texte":"Une réparation sans compte rendu écrit n''existe pas : six mois plus tard, tout est à refaire depuis le début."},{"accroche":"Réparer ou remplacer se décide dans l''urgence.","texte":"La fin de vie se subit au lieu d''être pilotée, et l''achat se fait en catastrophe."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"La recherche de la cause racine","texte":"mesures, relevés, analyse des données de l''automate, essais en conditions réelles. On cherche le pourquoi, pas seulement le quoi."},"benefice":"La panne sort du planning au lieu d''être entretenue tous les trimestres."},{"prestation":{"accroche":"La remise en état ou le remplacement","texte":"composant d''origine ou équivalent validé, réglage, contrôle dimensionnel, remise en service progressive."},"benefice":"L''équipement retrouve sa fiabilité, pas seulement sa capacité à démarrer."},{"prestation":{"accroche":"Le bilan écrit à chaque passage","texte":"cause identifiée, travaux, pièces changées, recommandations pour éviter la récidive."},"benefice":"La connaissance reste chez vous, dans votre GMAO, pas dans la tête d''un intervenant."},{"prestation":{"accroche":"L''aide à trancher entre réparer, rétrofiter et remplacer","texte":", chiffres en main."},"benefice":"La fin de vie se pilote deux ans à l''avance au lieu de se subir un vendredi soir."},{"prestation":{"accroche":"La bascule vers la surveillance après réparation","texte":"vous connaissez désormais l''organe fragile, il ne reste qu''à le suivre."},"benefice":"Un correctif de moins dans six mois, pour un coût de surveillance faible."},{"prestation":{"accroche":"L''astreinte 24/24 et 7/7 en option","texte":", partout en France."},"benefice":"Une casse le samedi ne devient pas un lundi perdu."}],"prose":[{"texte":"Machine à l''arrêt maintenant ? Voir le [dépannage industriel](/offres/depannage-industriel/). Pour ne plus payer ses pannes à l''unité, voir le [contrat de maintenance Zéro arrêt](/offres/zero-arret/). Migen est une [entreprise de maintenance industrielle](/offres/) présente partout en France."}]},{"type":"deroule","etapes":[{"titre":"Qualification par téléphone.","texte":"Équipement, symptôme, historique, contraintes du site. Cinq minutes ici font gagner deux heures sur place."},{"titre":"Choix du bon technicien.","texte":"Nous mobilisons le profil dont la compétence correspond au matériel, pas celui qui est simplement libre."},{"titre":"Sécurisation et consignation.","texte":"Plan de prévention, autorisations, règles de votre site appliquées avant le premier tournevis."},{"titre":"Recherche de la cause racine.","texte":"Mesures, relevés, analyse des données de l''automate, essais en conditions réelles."},{"titre":"Remise en état ou remplacement.","texte":"Composant d''origine ou équivalent validé, réglage, contrôle dimensionnel, remise en service progressive et essais en charge."},{"titre":"Bilan écrit.","texte":"Cause identifiée, travaux réalisés, pièces changées, recommandations. Le dossier machine s''enrichit à chaque passage."}]},{"type":"garanties","puces":[{"accroche":"Une réparation sans bilan écrit n''existe pas.","texte":"Si le technicien repart sans compte rendu, la connaissance repart avec lui. Le nôtre est exploitable dans votre GMAO et vous reste, même si vous changez de prestataire."},{"accroche":"Le bon profil, pas le profil disponible.","texte":"Chaque intervenant a passé une évaluation technique et comportementale en entretien, menée par un homme du métier, seuls 10 % des candidats sont retenus."},{"accroche":"Le conseil indépendant du constructeur.","texte":"Nous ne vendons pas de machines, donc notre intérêt n''est jamais de vous en faire acheter une. Réparer, rétrofiter ou remplacer : la recommandation se décide sur vos chiffres."}]},{"type":"cta","question":"Besoin qu''une panne qui revient tous les deux mois soit réglée pour de bon ?","bouton":"Demander une intervention","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure, astreinte 24/24 et 7/7."}]'::jsonb) where path = '/expertises/types-de-maintenance/maintenance-curative/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Maintenance curative des convoyeurs, trieurs et packaging, logistique","texte":"deux techniciens en poste sur site, dédiés au maintien des équipements","lienLibelle":"Étude de cas GLS : maintenance curative","lienHref":"/preuves/gls-maintenance-curative/"},{"titre":"Diagnostic sur site et réparation d''un parc machines défaillant, industrie lyonnaise","texte":"remise en état sans rachat de matériel neuf","lienLibelle":"Étude de cas JOINT LYONNAIS : défaillances machines","lienHref":"/preuves/joint-lyonnais/"},{"titre":"Remise en état d''un site de traitement des eaux industrielles, environnement","texte":"un électromécanicien habilité risque chimique mobilisé six mois","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"Maintenance préventive et curative des lignes de production, jeux et loteries","texte":"un technicien affecté en continu sur un site proche de Paris","lienLibelle":"Étude de cas FDJ : site proche de Paris","lienHref":"/preuves/fdj/"},{"titre":"Maintenance des centres d''usinage, presses et machines à commande numérique, automobile","texte":"un technicien intégré à temps plein","lienLibelle":"Étude de cas VOIT : site du Grand Est","lienHref":"/preuves/voit-grand-est/"},{"titre":"Maintenance préventive et curative d''une fonderie et d''un usinage, automobile","texte":"tenue 7 jours sur 7, depuis octobre 2023","lienLibelle":"Étude de cas STELLANTIS : fonderie de Sept-Fons","lienHref":"/preuves/stellantis-fonderie-sept-fons/"}]},{"type":"objections","questions":[{"question":"Quelle différence entre maintenance curative et corrective ?","reponse":"La corrective est la famille, la curative en est la branche définitive. Toute maintenance curative est corrective. L''inverse est faux, puisque le dépannage palliatif appartient lui aussi à la corrective, sans traiter la cause."},{"question":"La maintenance curative est-elle planifiable ?","reponse":"Oui, dès que la machine tient en mode dégradé. On sécurise la production, on commande les pièces sans transport express, puis on programme les travaux sur une fenêtre d''arrêt. C''est le meilleur des deux mondes, et le moyen le plus simple de supprimer les surcoûts d''urgence."},{"question":"Combien coûte une intervention curative ?","reponse":"Le chiffrage se fait sur devis. La question utile n''est pas le tarif horaire mais le coût complet : main d''œuvre, pièce, transport, production perdue, et la récidive si la cause n''est pas traitée. Nous détaillons ces postes avant l''intervention, pas après."},{"question":"Intervenez-vous en urgence, la nuit et le week-end ?","reponse":"Oui, partout en France, avec une astreinte 24/24 et 7/7 en option. Appelez le 04 78 33 72 05 : nous qualifions la situation avec vous et nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30."},{"question":"Qui intervient, et avec quelles habilitations ?","reponse":"Des techniciens salariés de Migen, évalués en entretien technique et comportemental, 10 % des candidats retenus. Les autorisations exigées par votre installation sont vérifiées avant le déplacement, et le plan de prévention est signé et appliqué."},{"question":"Pouvez-vous intégrer un professionnel dans notre équipe sur site ?","reponse":"Oui, en prestation de services : un homme de métier Migen travaille dans vos murs pour une durée définie avec vous, évalué au même niveau que pour nos interventions ponctuelles. Décrivez le besoin, nous vous disons franchement si l''expertise est chez nous."}]},{"type":"ctaFinal","question":"Besoin de solder une dette technique qui traîne depuis six mois ?","bouton":"Demander une intervention","rappel":"04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure, astreinte 24/24 et 7/7."}]'::jsonb) where path = '/expertises/types-de-maintenance/maintenance-curative/';
